+@page "/catalog"
+@rendermode InteractiveServer
+@using sv_e4a49a40275745339ae147dc52d4c8f1.Components.Catalog
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<div class="container-fluid py-3">
+    <div class="row">
+        @* Left sidebar — ~25% width *@
+        <div class="col-md-3">
+            <CatalogSidebar Categories="_categories" OnFilterApplied="HandleFilterApplied" />
+        </div>
+
+        @* Main content — ~75% width *@
+        <div class="col-md-9">
+            @if (_loading)
+            {
+                <div class="d-flex justify-content-center py-5">
+                    <div class="spinner-border text-primary" role="status">
+                        <span class="visually-hidden">Loading...</span>
+                    </div>
+                </div>
+            }
+            else if (_error is not null)
+            {
+                <div class="alert alert-danger" role="alert">
+                    <strong>Error:</strong> @_error
+                    <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadProducts">Retry</button>
+                </div>
+            }
+            else if (_result is not null && _result.Items.Count == 0)
+            {
+                <div class="alert alert-info" role="alert">
+                    No products found matching your criteria.
+                </div>
+            }
+            else if (_result is not null)
+            {
+                <CatalogToolbar SortBy="@_sortBy"
+                                TotalCount="_result.TotalCount"
+                                Page="_result.Page"
+                                PageSize="_result.PageSize"
+                                OnSortChanged="HandleSortChanged" />
+
+                <ProductGrid Products="_result.Items"
+                             OnProductSelected="HandleProductSelected"
+                             OnAddToCart="HandleAddToCart" />
+
+                <CatalogPagination Page="_result.Page"
+                                   TotalCount="_result.TotalCount"
+                                   PageSize="_result.PageSize"
+                                   OnPageChanged="HandlePageChanged" />
+            }
+        </div>
+    </div>
+</div>
+
+@code {
+    /// <summary>Raised when a product card is clicked so the parent/layout can navigate to a detail page.</summary>
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private List<string> _categories = [];
+    private PagedResult<Product>? _result;
+    private ProductFilter _filter = new(null, null, null, false);
+    private string _sortBy = "price_asc";
+    private int _page = 1;
+    private const int PageSize = 12;
+    private bool _loading = true;
+    private string? _error;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
+            await Task.WhenAll(categoriesTask, productsTask);
+
+            _categories = categoriesTask.Result;
+            _result = productsTask.Result;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            _result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task HandleFilterApplied(ProductFilter filter)
+    {
+        _filter = filter;
+        _page = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleSortChanged(string sortBy)
+    {
+        _sortBy = sortBy;
+        _page = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        _page = page;
+        await LoadProducts();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder — wire up to a cart service as needed
+        return Task.CompletedTask;
+    }
+}
+

